/* 3mm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "3mm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl))
{
  int i, j;

  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
  for (i = 0; i < nj; i++)
    for (j = 0; j < nm; j++)
      C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
  for (i = 0; i < nm; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* --------------------------------------------------------------------
 * Tunable constants for the kernel.
 *
 * POLY_3MM_OMP_MIN_WORK_* controls when OpenMP parallelization is
 * enabled for each matrix multiplication (measured in "scalar updates").
 * These are compile-time constants and can be tuned for a given machine.
 * ------------------------------------------------------------------ */
#ifndef POLY_3MM_OMP_MIN_WORK_E
# define POLY_3MM_OMP_MIN_WORK_E  32768L
#endif

#ifndef POLY_3MM_OMP_MIN_WORK_F
# define POLY_3MM_OMP_MIN_WORK_F  32768L
#endif

#ifndef POLY_3MM_OMP_MIN_WORK_G
# define POLY_3MM_OMP_MIN_WORK_G  32768L
#endif


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_3mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop
  /* Cache-friendly, parallelized version of the original 3mm kernel.
   *
   * Key points:
   *  - The reduction dimension (k) is still traversed in increasing
   *    order for every output element. This preserves the original
   *    floating-point evaluation order.
   *  - Loops are reordered to i-k-j for all three multiplications so
   *    that the innermost loop walks contiguous memory in row-major
   *    arrays (B, D, F, and the outputs).
   *  - Local restrict-qualified pointers are used to help the compiler
   *    with alias analysis and vectorization.
   *  - OpenMP parallelization is applied over the outer i-dimension of
   *    each multiplication, guarded by tunable minimum-work thresholds.
   */

  /* Runtime problem sizes used for bounds (PolyBench may shrink them). */
  const int n_i = _PB_NI;
  const int n_j = _PB_NJ;
  const int n_k = _PB_NK;
  const int n_l = _PB_NL;
  const int n_m = _PB_NM;

  /* Local restrict-qualified view of the 2D arrays.
   * POLYBENCH_2D parameters decay to VLA pointers, so this is only an
   * alias that provides additional 'restrict' information to the
   * optimizer; it does not change the underlying storage layout. */
  DATA_TYPE (*restrict E_)[nj] = (DATA_TYPE (*)[nj]) E;
  DATA_TYPE (*restrict A_)[nk] = (DATA_TYPE (*)[nk]) A;
  DATA_TYPE (*restrict B_)[nj] = (DATA_TYPE (*)[nj]) B;

  DATA_TYPE (*restrict F_)[nl] = (DATA_TYPE (*)[nl]) F;
  DATA_TYPE (*restrict C_)[nm] = (DATA_TYPE (*)[nm]) C;
  DATA_TYPE (*restrict D_)[nl] = (DATA_TYPE (*)[nl]) D;

  DATA_TYPE (*restrict G_)[nl] = (DATA_TYPE (*)[nl]) G;

  /* ------------------------------------------------------------------
   * E := A * B
   *
   * Original:
   *   for i
   *     for j
   *       E[i][j] = 0;
   *       for k
   *         E[i][j] += A[i][k] * B[k][j];
   *
   * New:
   *   for i
   *     zero row E[i][*];
   *     for k
   *       for j
   *         E[i][j] += A[i][k] * B[k][j];
   *
   * For each fixed (i, j), k still runs from 0 to n_k-1 in ascending
   * order, so the arithmetic order of the reduction is unchanged.
   * ------------------------------------------------------------------ */
  {
    const long work_e = (long)n_i * (long)n_j * (long)n_k;

    #pragma omp parallel for schedule(static) private(j,k) \
            if (work_e >= POLY_3MM_OMP_MIN_WORK_E)
    for (i = 0; i < n_i; ++i)
    {
      /* Pointer to the i-th row of E, kept constant inside the loop. */
      DATA_TYPE *restrict const E_row = &E_[i][0];

      /* Initialize the whole row once. */
      for (j = 0; j < n_j; ++j)
        E_row[j] = SCALAR_VAL(0.0);

      for (k = 0; k < n_k; ++k)
      {
        const DATA_TYPE a_ik = A_[i][k];
        const DATA_TYPE *restrict B_row = &B_[k][0];

        /* Innermost loop walks contiguous memory in both E_row and B_row. */
        for (j = 0; j < n_j; ++j)
          E_row[j] += a_ik * B_row[j];
      }
    }
  }

  /* ------------------------------------------------------------------
   * F := C * D
   *
   * Same transformation pattern as above:
   *   - Row-wise initialization of F.
   *   - i-k-j ordering for better locality.
   *   - k-order preserved for each (i, j) element.
   * ------------------------------------------------------------------ */
  {
    const long work_f = (long)n_j * (long)n_l * (long)n_m;

    #pragma omp parallel for schedule(static) private(j,k) \
            if (work_f >= POLY_3MM_OMP_MIN_WORK_F)
    for (i = 0; i < n_j; ++i)
    {
      DATA_TYPE *restrict const F_row = &F_[i][0];

      for (j = 0; j < n_l; ++j)
        F_row[j] = SCALAR_VAL(0.0);

      for (k = 0; k < n_m; ++k)
      {
        const DATA_TYPE c_ik = C_[i][k];
        const DATA_TYPE *restrict D_row = &D_[k][0];

        for (j = 0; j < n_l; ++j)
          F_row[j] += c_ik * D_row[j];
      }
    }
  }

  /* ------------------------------------------------------------------
   * G := E * F
   *
   * Original:
   *   for i
   *     for j
   *       G[i][j] = 0;
   *       for k
   *         G[i][j] += E[i][k] * F[k][j];
   *
   * New:
   *   for i
   *     zero row G[i][*];
   *     for k
   *       for j
   *         G[i][j] += E[i][k] * F[k][j];
   *
   * Again, for every (i, j), the accumulation visits k in increasing
   * order only, so the arithmetic is the same while memory accesses
   * become more regular.
   * ------------------------------------------------------------------ */
  {
    const long work_g = (long)n_i * (long)n_l * (long)n_j;

    #pragma omp parallel for schedule(static) private(j,k) \
            if (work_g >= POLY_3MM_OMP_MIN_WORK_G)
    for (i = 0; i < n_i; ++i)
    {
      DATA_TYPE *restrict const G_row = &G_[i][0];

      for (j = 0; j < n_l; ++j)
        G_row[j] = SCALAR_VAL(0.0);

      for (k = 0; k < n_j; ++k)
      {
        const DATA_TYPE e_ik = E_[i][k];
        const DATA_TYPE *restrict F_row = &F_[k][0];

        for (j = 0; j < n_l; ++j)
          G_row[j] += e_ik * F_row[j];
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;
  int nm = NM;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(E, DATA_TYPE, NI, NJ, ni, nj);
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, NI, NK, ni, nk);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, NK, NJ, nk, nj);
  POLYBENCH_2D_ARRAY_DECL(F, DATA_TYPE, NJ, NL, nj, nl);
  POLYBENCH_2D_ARRAY_DECL(C, DATA_TYPE, NJ, NM, nj, nm);
  POLYBENCH_2D_ARRAY_DECL(D, DATA_TYPE, NM, NL, nm, nl);
  POLYBENCH_2D_ARRAY_DECL(G, DATA_TYPE, NI, NL, ni, nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_3mm (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(E),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(F),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D),
	      POLYBENCH_ARRAY(G));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(G)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(E);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(F);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);
  POLYBENCH_FREE_ARRAY(G);

  return 0;
}
