}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations:
   - Rewritten all three matrix multiplications in an outer-product
     style (i-k-j) which keeps both source matrices and the result
     accessed row-contiguously in the innermost loop.
   - Flattened the 2D arrays to 1D, restrict-qualified pointers to
     give the compiler stronger aliasing information and enable
     aggressive vectorization.
   - Added optional blocking on the innermost j-loop, tunable via
     T3MM_JBLOCK, to improve cache reuse for large problems.
   - Added OpenMP parallel-for pragmas on the outer i-loops of each
     multiplication. Each iteration of i touches disjoint rows, so
     there are no data races and the order of operations for each
     element is preserved (k still iterates in ascending order).
*/
static void __attribute__((flatten, noinline))
kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  /* Use PolyBench's possibly scaled loop bounds. */
  const int ni_ = _PB_NI;
  const int nj_ = _PB_NJ;
  const int nk_ = _PB_NK;
  const int nl_ = _PB_NL;
  const int nm_ = _PB_NM;

  /* Leading dimensions (column counts) for each matrix when viewed as
     a flat, row-major array. */
  const int ldE = nj;
  const int ldA = nk;
  const int ldB = nj;
  const int ldF = nl;
  const int ldC = nm;
  const int ldD = nl;
  const int ldG = nl;

  /* Flattened, restrict-qualified views of the matrices.
     All matrices are allocated disjointly by PolyBench, so the
     restrict qualifiers are valid and allow the compiler to
     assume no aliasing between them. */
  DATA_TYPE *restrict E_ = (DATA_TYPE*)E;
  DATA_TYPE *restrict A_ = (DATA_TYPE*)A;
  DATA_TYPE *restrict B_ = (DATA_TYPE*)B;
  DATA_TYPE *restrict F_ = (DATA_TYPE*)F;
  DATA_TYPE *restrict C_ = (DATA_TYPE*)C;
  DATA_TYPE *restrict D_ = (DATA_TYPE*)D;
  DATA_TYPE *restrict G_ = (DATA_TYPE*)G;

  int i, j, k;

#pragma scop
  /* E := A*B
     Outer-product formulation with i as the outermost loop:
       for each row i of E,
         E[i,*] = 0;
         for each k
           E[i,*] += A[i,k] * B[k,*];
     This keeps A, B, and E accessed contiguously in memory in the
     innermost loop and preserves the accumulation order over k. */
#pragma omp parallel for schedule(static) private(j, k)
  for (i = 0; i < ni_; i++)
    {
      const size_t rowE = (size_t)i * (size_t)ldE;
      const size_t rowA = (size_t)i * (size_t)ldA;

      /* Initialize row i of E. */
      for (j = 0; j < nj_; j++)
        E_[rowE + (size_t)j] = SCALAR_VAL(0.0);

      for (k = 0; k < nk_; ++k)
        {
          const DATA_TYPE aik = A_[rowA + (size_t)k];
          const size_t rowB = (size_t)k * (size_t)ldB;

#if T3MM_JBLOCK > 1
          /* Block the j-loop to improve cache reuse for B and E.
             For each block, j still increases monotonically, and
             for each element E[i,j] the k-loop is unchanged and
             runs in ascending order, so floating-point semantics
             are preserved. */
          for (int jb = 0; jb < nj_; jb += T3MM_JBLOCK)
            {
              const int jend = jb + T3MM_JBLOCK < nj_ ? jb + T3MM_JBLOCK : nj_;
              for (j = jb; j < jend; ++j)
                E_[rowE + (size_t)j] += aik * B_[rowB + (size_t)j];
            }
#else
          for (j = 0; j < nj_; ++j)
            E_[rowE + (size_t)j] += aik * B_[rowB + (size_t)j];
#endif
        }
    }

  /* F := C*D, same optimization strategy as for E := A*B. */
#pragma omp parallel for schedule(static) private(j, k)
  for (i = 0; i < nj_; i++)
    {
      const size_t rowF = (size_t)i * (size_t)ldF;
      const size_t rowC = (size_t)i * (size_t)ldC;

      for (j = 0; j < nl_; j++)
        F_[rowF + (size_t)j] = SCALAR_VAL(0.0);

      for (k = 0; k < nm_; ++k)
        {
          const DATA_TYPE cik = C_[rowC + (size_t)k];
          const size_t rowD = (size_t)k * (size_t)ldD;

#if T3MM_JBLOCK > 1
          for (int jb = 0; jb < nl_; jb += T3MM_JBLOCK)
            {
              const int jend = jb + T3MM_JBLOCK < nl_ ? jb + T3MM_JBLOCK : nl_;
              for (j = jb; j < jend; ++j)
                F_[rowF + (size_t)j] += cik * D_[rowD + (size_t)j];
            }
#else
          for (j = 0; j < nl_; ++j)
            F_[rowF + (size_t)j] += cik * D_[rowD + (size_t)j];
#endif
        }
    }

  /* G := E*F, again using an outer-product formulation. */
#pragma omp parallel for schedule(static) private(j, k)
  for (i = 0; i < ni_; i++)
    {
      const size_t rowG = (size_t)i * (size_t)ldG;
      const size_t rowE2 = (size_t)i * (size_t)ldE;

      for (j = 0; j < nl_; j++)
        G_[rowG + (size_t)j] = SCALAR_VAL(0.0);

      for (k = 0; k < nj_; ++k)
        {
          const DATA_TYPE eik = GASSUME_ALIGNED E_[rowE2 + (size_t)k];
          const size_t rowF = (size_t)k * (size_t)ldF;

#if T3MM_JBLOCK > 1
          for (int jb = 0; jb < nl_; jb += T3MM_JBLOCK)
            {
              const int jend = jb + T3MM_JBLOCK < nl_ ? jb + T3MM_JBLOCK : nl_;
              for (j = jb; j < jend; ++j)
                G_[rowG + (size_t)j] += eik * F_[rowF + (size_t)j];
            }
#else
          for (j = 0; j < nl_; ++j)
            G_[rowG + (size_t)j] += eik * F_[rowF + (size_t)j];
#endif
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;
  int nm = NM;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(E, DATA_TYPE, NI, NJ, ni, nj);
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, NI, NK, ni, nk);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, NK, NJ, nk, nj);
  POLYBENCH_2D_ARRAY_DECL(F, DATA_TYPE, NJ, NL, nj, nl);
  POLYBENCH_2D_ARRAY_DECL(C, DATA_TYPE, NJ, NM, nj, nm);
  POLYBENCH_2D_ARRAY_DECL(D, DATA_TYPE, NM, NL, nm, nl);
  POLYBENCH_2D_ARRAY_DECL(G, DATA_TYPE, NI, NL, ni, nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_3mm (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(E),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(F),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D),
	      POLYBENCH_ARRAY(G));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(G)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(E);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(F);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);
  POLYBENCH_FREE_ARRAY(G);

  return 0;
}
