/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Explicit matrix-multiply blocking (tiling) in all three GEMMs to
 *    improve cache reuse and data locality.
 *  - Reordered inner loops so that the column (j) dimension is innermost,
 *    giving contiguous accesses in the right-hand-side matrices and in the
 *    outputs, which helps vectorization.
 *  - Separate zero-initialization of E, F, G to keep the accumulation loops
 *    simple and enable better transformations.
 *  - Use of local 'restrict' pointer aliases to eliminate potential
 *    aliasing between the different matrices.
 *  - Optional OpenMP parallelization over (i,j) tiles; when compiled without
 *    -fopenmp, the pragmas are ignored and the code remains sequential.
 *
 * The order of floating-point operations for each individual output element
 * is preserved with respect to the original code: for every (i,j) pair,
 * the partial sums are accumulated in increasing k order, only grouped into
 * tiles. This keeps numerical results bitwise identical to the original.
 */
static
void kernel_3mm [[gnu::flatten, gnu::noinline]](
		int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

  /* Local restrict-qualified aliases to help the compiler with
     vectorization and alias analysis.  These all point to the same
     memory as the corresponding arguments but carry 'restrict'
     guarantees that different matrices do not overlap. */
  DATA_TYPE       (* restrict E_)[nj] = E;
  const DATA_TYPE (* restrict A_)[nk] = A;
  const DATA_TYPE (* restrict B_)[nj] = B;

  DATA_TYPE       (* restrict F_)[nl] = F;
  const DATA_TYPE (* restrict C_)[nm] = C;
  const DATA_TYPE (* restrict D_)[nl] = D;

  DATA_TYPE       (* restrict G_)[nl] = G;

#pragma scop
  /* -----------------------------------------------------------------------
   * E := A * B
   *   A: ni x nk
   *   B: nk x nj
   *   E: ni x nj
   * ---------------------------------------------------------------------*/

  /* Zero-initialize E.  O(ni*nj), negligible vs. O(ni*nj*nk) work. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE * restrict Ei = E_[i];
    for (j = 0; j < _PB_NJ; j++)
      Ei[j] = SCALAR_VAL(0.0);
  }

  /* Tiled matrix multiplication:
     Outer tiles (ii, jj) partition E's rows/columns.
     Inner k-tiles preserve increasing-k accumulation order. */
#pragma omp parallel for collapse(2) private(i,j,k) schedule(static)
  for (int ii = 0; ii < _PB_NI; ii += T_I) {
    for (int jj = 0; jj < _PB_NJ; jj += T_J) {

      int i_end = ii + T_I;
      if (i_end > _PB_NI) i_end = _PB_NI;

      int j_end = jj + T_J;
      if (j_end > _PB_NJ) j_end = _PB_NJ;

      for (i = ii; i < i_end; ++i) {
        DATA_TYPE       * restrict Ei = E_[i];
        const DATA_TYPE * restrict Ai = A_[i];

        /* Sweep k dimension in tiles, but always increasing k. */
        for (int kk = 0; kk < _PB_NK; kk += T_K) {
          int k_end = kk + T_K;
          if (k_end > _PB_NK) k_end = _PB_NK;

          for (k = kk; k < k_end; ++k) {
            const DATA_TYPE aik = Ai[k];
            const DATA_TYPE * restrict Bk = B_[k];

            /* Innermost loop over j gives contiguous accesses in B and E. */
            for (j = jj; j < j_end; ++j) {
              Ei[j] += aik * Bk[j];
            }
          }
        }
      }
    }
  }

  /* -----------------------------------------------------------------------
   * F := C * D
   *   C: nj x nm
   *   D: nm x nl
   *   F: nj x nl
   * Same blocked algorithm adapted to the different dimensions.
   * ---------------------------------------------------------------------*/

  /* Zero-initialize F. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < _PB_NJ; i++) {
    DATA_TYPE * restrict Fi = F_[i];
    for (j = 0; j < _PB_NL; j++)
      Fi[j] = SCALAR_VAL(0.0);
  }

#pragma omp parallel for collapse(2) private(i,j,k) schedule(static)
  for (int ii = 0; ii < _PB_NJ; ii += T_I) {
    for (int jj = 0; jj < _PB_NL; jj += T_J) {

      int i_end = ii + T_I;
      if (i_end > _PB_NJ) i_end = _PB_NJ;

      int j_end = jj + T_J;
      if (j_end > _PB_NL) j_end = _PB_NL;

      for (i = ii; i < i_end; ++i) {
        DATA_TYPE       * restrict Fi = F_[i];
        const DATA_TYPE * restrict Ci = C_[i];

        for (int kk = 0; kk < _PB_NM; kk += T_K) {
          int k_end = kk + T_K;
          if (k_end > _PB_NM) k_end = _PB_NM;

          for (k = kk; k < k_end; ++k) {
            const DATA_TYPE cik = Ci[k];
            const DATA_TYPE * restrict Dk = D_[k];

            for (j = jj; j < j_end; ++j) {
              Fi[j] += cik * Dk[j];
            }
          }
        }
      }
    }
  }

  /* -----------------------------------------------------------------------
   * G := E * F
   *   E: ni x nj
   *   F: nj x nl
   *   G: ni x nl
   * Same blocked GEMM pattern.
   * ---------------------------------------------------------------------*/

  /* Zero-initialize G. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE * restrict Gi = G_[i];
    for (j = 0; j < _PB_NL; j++)
      Gi[j] = SCALAR_VAL(0.0);
  }

#pragma omp parallel for collapse(2) private(i,j,k) schedule(static)
  for (int ii = 0; ii < _PB_NI; ii += T_I) {
    for (int jj = 0; jj < _PB_NL; jj += T_J) {

      int i_end = ii + T_I;
      if (i_end > _PB_NI) i_end = _PB_NI;

      int j_end = jj + T_J;
      if (j_end > _PB_NL) j_end = _PB_NL;

      for (i = ii; i < i_end; ++i) {
        DATA_TYPE       * restrict Gi = G_[i];
        const DATA_TYPE * restrict Ei = E_[i];

        for (int kk = 0; kk < _PB_NJ; kk += T_K) {
          int k_end = kk + T_K;
          if (k_end > _PB_NJ) k_end = _PB_NJ;

          for (k = kk; k < k_end; ++k) {
            const DATA_TYPE eik = Ei[k];
            const DATA_TYPE * restrict Fk = F_[k];

            for (j = jj; j < j_end; ++j) {
              Gi[j] += eik * Fk[j];
            }
          }
        }
      }
    }
  }
#pragma endscop

}


