		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl))
{
  int i, j;

  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
  for (i = 0; i < nj; i++)
    for (j = 0; j < nm; j++)
      C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
  for (i = 0; i < nm; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_3mm [[gnu::flatten, gnu::noinline]] (int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  /* Create restrict-qualified local aliases.
   *
   * PolyBench allocates each of these arrays separately, so they do not
   * alias each other.  Telling the compiler this with 'restrict' improves
   * vectorization and scheduling while leaving the numerical computation
   * unchanged.
   *
   * The dimensions use the _PB_* macros so that the pointer types match
   * the actual leading dimensions of the VLAs passed in.
   */
  DATA_TYPE (*restrict E_)[_PB_NJ]        = (DATA_TYPE (*restrict)[_PB_NJ])E;
  const DATA_TYPE (*restrict A_)[_PB_NK]  = (const DATA_TYPE (*restrict)[_PB_NK])A;
  const DATA_TYPE (*restrict B_)[_PB_NJ]  = (const DATA_TYPE (*restrict)[_PB_NJ])B;

  DATA_TYPE (*restrict F_)[_PB_NL]        = (DATA_TYPE (*restrict)[_PB_NL])F;
  const DATA_TYPE (*restrict C_)[_PB_NM]  = (const DATA_TYPE (*restrict)[_PB_NM])C;
  const DATA_TYPE (*restrict D_)[_PB_NL]  = (const DATA_TYPE (*restrict)[_PB_NL])D;

  DATA_TYPE (*restrict G_)[_PB_NL]        = (DATA_TYPE (*restrict)[_PB_NL])G;

#pragma scop
  /* -----------------------------------------------------------------------
   * E := A * B
   *
   * Original code (per element):
   *   for i
   *     for j
   *       E[i][j] = 0;
   *       for k
   *         E[i][j] += A[i][k] * B[k][j];
   *
   * Transformation:
   *   1. Separate initialization of E from the multiplication.
   *   2. Reorder loops to i -> jj (j block) -> kk (k block) -> k -> j.
   *      This improves spatial locality for:
   *        - rows of B (B[k][j]) and
   *        - rows of E (E[i][j]),
   *      while preserving the accumulation order over k for every (i,j).
   *   3. Parallelize the outer i-loop with OpenMP.
   * ---------------------------------------------------------------------*/

  /* Zero-initialize E */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < _PB_NI; ++i) {
    DATA_TYPE *restrict E_row = &E_[i][0];
    for (int j = 0; j < _PB_NJ; ++j) {
      E_row[j] = SCALAR_VAL(0.0);
    }
  }

  /* Blocked matrix multiplication E = A * B */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < _PB_NI; ++i) {
    const DATA_TYPE *restrict A_row = &A_[i][0];
    DATA_TYPE *restrict E_row       = &E_[i][0];

    for (int kk = 0; kk < _PB_NK; kk += MM_E_BLOCK_K) {
      const int kend = (kk + MM_E_BLOCK_K < _PB_NK) ? (kk + MM_E_BLOCK_K) : _PB_NK;

      for (int jj = 0; jj < _PB_NJ; jj += MM_E_BLOCK_J) {
        const int jend = (jj + MM_E_BLOCK_J < _PB_NJ) ? (jj + MM_E_BLOCK_J) : _PB_NJ;

        for (int k = kk; k < kend; ++k) {
          const DATA_TYPE a_ik = A_row[k];
          const DATA_TYPE *restrict B_row = &B_[k][0];

          /* Inner-most loop has unit-stride accesses to both E_row and B_row. */
          for (int j = jj; j < jend; ++j) {
            E_row[j] += a_ik * B_row[j];
          }
        }
      }
    }
  }

  /* -----------------------------------------------------------------------
   * F := C * D
   *
   * Same set of transformations as for E := A * B.
   * Dimensions:
   *   C: (_PB_NJ x _PB_NM)
   *   D: (_PB_NM x _PB_NL)
   *   F: (_PB_NJ x _PB_NL)
   * ---------------------------------------------------------------------*/

  /* Zero-initialize F */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < _PB_NJ; ++i) {
    DATA_TYPE *restrict F_row = &F_[i][0];
    for (int j = 0; j < _PB_NL; ++j) {
      F_row[j] = SCALAR_VAL(0.0);
    }
  }

  /* Blocked matrix multiplication F = C * D */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < _PB_NJ; ++i) {
    const DATA_TYPE *restrict C_row = &C_[i][0];
    DATA_TYPE *restrict F_row       = &F_[i][0];

    for (int kk = 0; kk < _PB_NM; kk += MM_F_BLOCK_K) {
      const int kend = (kk + MM_F_BLOCK_K < _PB_NM) ? (kk + MM_F_BLOCK_K) : _PB_NM;

      for (int jj = 0; jj < _PB_NL; jj += MM_F_BLOCK_J) {
        const int jend = (jj + MM_F_BLOCK_J < _PB_NL) ? (jj + MM_F_BLOCK_J) : _PB_NL;

        for (int k = kk; k < kend; ++k) {
          const DATA_TYPE c_ik = C_row[k];
          const DATA_TYPE *restrict D_row = &D_[k][0];

          for (int j = jj; j < jend; ++j) {
            F_row[j] += c_ik * D_row[j];
          }
        }
      }
    }
  }

  /* -----------------------------------------------------------------------
   * G := E * F
   *
   * Same blocking and parallelization strategy.
   * Dimensions:
   *   E: (_PB_NI x _PB_NJ)
   *   F: (_PB_NJ x _PB_NL)
   *   G: (_PB_NI x _PB_NL)
   * ---------------------------------------------------------------------*/

  /* Zero-initialize G */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < _PB_NI; ++i) {
    DATA_TYPE *restrict G_row = &G_[i][0];
    for (int j = 0; j < _PB_NL; ++j) {
      G_row[j] = SCALAR_VAL(0.0);
    }
  }

  /* Blocked matrix multiplication G = E * F */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < _PB_NI; ++i) {
    const DATA_TYPE *restrict E_row = &E_[i][0];
    DATA_TYPE *restrict G_row       = &G_[i][0];

    for (int kk = 0; kk < _PB_NJ; kk += MM_G_BLOCK_K) {
      const int kend = (kk + MM_G_BLOCK_K < _PB_NJ) ? (kk + MM_G_BLOCK_K) : _PB_NJ;

      for (int jj = 0; jj < _PB_NL; jj += MM_G_BLOCK_J) {
        const int jend = (jj + MM_G_BLOCK_J < _PB_NL) ? (jj + MM_G_BLOCK_J) : _PB_NL;

        for (int k = kk; k < kend; ++k) {
          const DATA_TYPE e_ik = E_row[k];
          const DATA_TYPE *restrict F_row_k = &F_[k][0];

          for (int j = jj; j < jend; ++j) {
            G_row[j] += e_ik * F_row_k[j];
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;
  int nm = NM;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(E, DATA_TYPE, NI, NJ, ni, nj);
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, NI, NK, ni, nk);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, NK, NJ, nk, nj);
  POLYBENCH_2D_ARRAY_DECL(F, DATA_TYPE, NJ, NL, nj, nl);
  POLYBENCH_2D_ARRAY_DECL(C, DATA_TYPE, NJ, NM, nj, nm);
  POLYBENCH_2D_ARRAY_DECL(D, DATA_TYPE, NM, NL, nm, nl);
  POLYBENCH_2D_ARRAY_DECL(G, DATA_TYPE, NI, NL, ni, nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_3mm (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(E),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(F),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D),
	      POLYBENCH_ARRAY(G));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(G)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(E);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(F);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);
  POLYBENCH_FREE_ARRAY(G);

  return 0;
}
